package com.disasterrelief.controller;
import java.util.List; import com.disasterrelief.dto.*; import com.disasterrelief.model.*; import com.disasterrelief.service.ReliefService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/requests") public class EmergencyRequestController { private final ReliefService s; public EmergencyRequestController(ReliefService s){this.s=s;} @GetMapping public List<EmergencyRequest> all(){return s.requests();} @GetMapping("/{id}") public EmergencyRequest one(@PathVariable Long id){return s.request(id);} @PostMapping public ResponseEntity<EmergencyRequest> create(@Valid @RequestBody EmergencyRequestPayload x){return ResponseEntity.status(HttpStatus.CREATED).body(s.saveRequest(x,null));} @PutMapping("/{id}") public EmergencyRequest update(@PathVariable Long id,@Valid @RequestBody EmergencyRequestPayload x){return s.saveRequest(x,id);}@PutMapping("/{id}/status") public EmergencyRequest status(@PathVariable Long id,@Valid @RequestBody StatusUpdateRequest x){return s.updateStatus(id,x);}@GetMapping("/{id}/history") public List<RequestHistory> history(@PathVariable Long id){return s.history(id);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.deleteRequest(id);} }
